insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-bookkeeping-administration') and position=1),'australian-bookkeeping-workflow-gst-bas-and-role-boundaries','Australian Bookkeeping Workflow, GST, BAS, and Role Boundaries','Australian bookkeeping administration touches source documents, accounts payable, accounts receivable, bank transactions, GST, payroll, and reports. A VA can prepare clean records and exception lists, but professional or statutory judgment may belong to a bookkeeper, registered BAS or tax agent, accountant, payroll specialist, or business owner.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Understand the Australian bookkeeping cycle","Recognize GST and BAS terminology","Separate preparation from tax, BAS, accounting, and payroll advice"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Australian bookkeeping administration touches source documents, accounts payable, accounts receivable, bank transactions, GST, payroll, and reports. A VA can prepare clean records and exception lists, but professional or statutory judgment may belong to a bookkeeper, registered BAS or tax agent, accountant, payroll specialist, or business owner."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Source documents support transactions and audit trail.","AP tracks supplier obligations; AR tracks customer balances.","Bank reconciliation compares accounting records with bank activity.","GST coding can affect BAS reporting.","STP is an Australian payroll reporting workflow.","Authority depends on the task and the person''s qualifications."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Map the client''s accounting system and document flow.","Identify who approves bills, payments, coding, GST, payroll, and BAS.","Learn only the chart, tax-code, and coding rules approved for your role.","Define exception categories for reviewer escalation.","Record monthly, quarterly, and payroll cut-offs.","Never submit regulated declarations using another person''s authority."]},{"type":"callout","title":"Stay inside the role","text":"This course is administrative training, not tax, BAS, accounting, payroll, or financial advice. Do not decide GST treatment, lodge BAS, submit STP declarations, determine statutory entitlements, or provide professional advice unless qualified and authorized."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Treating bookkeeping as simple data entry","Copying GST treatment from a similar transaction without approval","Using software access to lodge reports","Deleting source documents after entry","Hiding unreconciled items to make reports look clean"]},{"type":"scenario","title":"Practice scenario","text":"A client gives you accounting-system access and says, ''Please handle the books.'' List the authority and workflow questions you need answered before touching GST, bank reconciliation, payroll, or BAS-related work."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Prepare clean records.","Know who owns judgment.","Preserve source evidence.","Escalate tax and statutory decisions."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-bookkeeping-administration') and position=1),'source-documents-invoices-bills-receipts-and-data-quality','Source Documents, Invoices, Bills, Receipts, and Data Quality','Bookkeeping quality begins with evidence. Invoices, bills, receipts, statements, and payment records should connect cleanly to the correct supplier, customer, date, amount, and business purpose.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Process source documents consistently","Detect duplicates and missing information","Create an auditable admin trail"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Bookkeeping quality begins with evidence. Invoices, bills, receipts, statements, and payment records should connect cleanly to the correct supplier, customer, date, amount, and business purpose."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Sales invoices and supplier bills represent different workflows.","A receipt is evidence of payment, not automatically a complete accounting record.","Duplicates can come from email, uploads, scans, integrations, or reissued documents.","Document numbers, dates, counterparties, amounts, and GST details may need review.","The original source should remain retrievable."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Identify document type and entity.","Check counterparty identity.","Search invoice number, amount, and date for duplicates.","Capture approved fields.","Attach or store the source evidence.","Flag missing or conflicting information.","Route uncertain coding or GST treatment.","Track approval and payment status."]},{"type":"callout","title":"Stay inside the role","text":"Do not alter original supplier documents or invent missing tax information."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Entering the same bill twice","Using payment date as invoice date without process basis","Assuming GST from the total","Replacing originals with screenshots","Ignoring supplier identity mismatch"]},{"type":"scenario","title":"Practice scenario","text":"Two emailed PDFs have the same supplier, amount, and invoice number but different filenames. Explain how you handle the duplicate risk before entry."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Evidence first.","Search for duplicates.","Preserve originals.","Escalate missing tax or coding information."]}]'::jsonb,30,2,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

