insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-bookkeeping-administration') and position=2),'accounts-payable-approvals-and-payment-preparation','Accounts Payable, Approvals, and Payment Preparation','A VA may enter bills, collect approvals, prepare payment information, and report due items. The key control is separating preparation from authorization and protecting supplier bank details.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Track bills from receipt to payment","Respect approval and spending authority","Prepare clean payment handoffs"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"A VA may enter bills, collect approvals, prepare payment information, and report due items. The key control is separating preparation from authorization and protecting supplier bank details."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Approval status should be visible.","Due dates matter, but cash-flow priority belongs to authorized decision-makers.","Supplier bank-detail changes are high-risk.","Credits and disputes can change the amount payable.","Payment evidence should link back to the bill."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Enter or verify the bill from source evidence.","Check duplicate status.","Route approval to the correct owner.","Verify changed bank details through the client''s approved method.","Prepare the approved payment list.","Do not release funds outside delegated authority.","Record payment evidence after confirmation.","Keep disputes and exceptions visible."]},{"type":"callout","title":"Stay inside the role","text":"Never approve your own payment batch unless the client''s controls explicitly permit it and your role is authorized. Treat supplier bank-detail changes as a fraud risk."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Paying to new bank details from email only","Marking a bill paid before evidence","Ignoring credits","Choosing which suppliers get paid from personal preference","Using another person''s credentials to bypass approval"]},{"type":"scenario","title":"Practice scenario","text":"A supplier emails new bank details one day before a large payment. Describe the verification and escalation process."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Separate preparation and approval.","Verify sensitive changes.","Use evidence for paid status.","Keep disputes visible."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-bookkeeping-administration') and position=2),'accounts-receivable-invoicing-credits-and-debtor-follow-up','Accounts Receivable, Invoicing, Credits, and Debtor Follow-Up','AR administration affects cash flow. The VA can create approved invoices, track balances, send statements or reminders, and record disputes while keeping concessions and accounting decisions with authorized staff.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Support clean customer invoicing","Track outstanding balances","Follow up without unauthorized concessions"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"AR administration affects cash flow. The VA can create approved invoices, track balances, send statements or reminders, and record disputes while keeping concessions and accounting decisions with authorized staff."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Invoices should come from approved goods or service data.","Credits and refunds require authorization.","Payment status should be evidence-based.","Debtor follow-up should reflect current history.","Disputed invoices need a different workflow from ordinary overdue balances."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm the invoice is ready to issue.","Check customer and billing details.","Send through the approved channel.","Track due date and payment status.","Verify no recent payment before follow-up.","Use approved reminder cadence.","Record promises or disputes.","Escalate credits, write-offs, payment plans, and collection decisions."]},{"type":"callout","title":"Stay inside the role","text":"Do not promise discounts, waive charges, create payment plans, or write off debt without authority."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Chasing paid invoices","Sending standard reminders to disputed accounts","Changing terms to get payment","Creating credits to clean aged receivables","Failing to record a payment promise"]},{"type":"scenario","title":"Practice scenario","text":"A long-term customer says they cannot pay the full invoice and asks for three instalments. Draft the admin response and escalation."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Invoice from approved data.","Verify before chasing.","Document disputes.","Keep concessions with authorized decision-makers."]}]'::jsonb,30,2,false,1,null,null,now(),now())
