insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-bookkeeping-administration') and position=3),'bank-reconciliation-preparation-and-exception-management','Bank Reconciliation Preparation and Exception Management','Bank reconciliation compares accounting records with actual bank activity. Software may suggest matches or categories, but the VA should follow approved rules and avoid forcing uncertain transactions just to reach a clean screen.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Understand the purpose of bank reconciliation","Prepare likely matches carefully","Create useful exception queues"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Bank reconciliation compares accounting records with actual bank activity. Software may suggest matches or categories, but the VA should follow approved rules and avoid forcing uncertain transactions just to reach a clean screen."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["A bank transaction may match an invoice, bill, expense, transfer, payroll entry, or another record.","Amount, date, reference, payee, and prior history can help identify a match.","Transfers and duplicate imports can create misleading patterns.","Unexplained items need an exception owner.","Reconciliation quality affects downstream reporting and GST or BAS preparation."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review bank transaction and evidence.","Search exact or likely approved matches.","Apply documented bank rules only when appropriate.","Do not create a transaction solely to clear the feed if purpose is unknown.","Flag unusual, personal-looking, duplicate, transfer, or unclear items.","Prepare an exception list for the reviewer.","Document resolved items."]},{"type":"callout","title":"Stay inside the role","text":"A software suggestion is not proof of accounting treatment. Escalate uncertain coding, GST, owner, loan, payroll, asset, or tax-sensitive items."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Accepting every suggested match","Creating fake descriptions to clear items","Treating personal-looking items as personal without review","Reconciling duplicates","Leaving no audit note on exceptions"]},{"type":"scenario","title":"Practice scenario","text":"A $2,450 bank transaction has a vendor name similar to a bill, but the amount differs. Explain the checks before matching or creating anything."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Reconcile from evidence.","Use rules carefully.","Keep exceptions visible.","Do not chase a zero balance at the expense of accuracy."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-bookkeeping-administration') and position=3),'payroll-stp-super-and-leave-administration-handoffs','Payroll, STP, Super, and Leave Administration Handoffs','Australian payroll can involve employee details, timesheets, earnings, leave, PAYG withholding, superannuation, and Single Touch Payroll reporting. A VA may collect and check inputs but should not assume authority to determine statutory treatment or submit declarations.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize Australian payroll admin concepts","Prepare clean payroll inputs","Keep STP and statutory declarations with authorized staff"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Australian payroll can involve employee details, timesheets, earnings, leave, PAYG withholding, superannuation, and Single Touch Payroll reporting. A VA may collect and check inputs but should not assume authority to determine statutory treatment or submit declarations."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["STP reports payroll information to the ATO.","Payroll data is highly sensitive.","Employee changes need effective dates and approval.","Super, tax, leave, awards, termination, and corrections can carry statutory implications.","Software calculations still depend on correct setup."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Collect approved timesheets and employee changes.","Check missing approvals and obvious anomalies.","Prepare the payroll exception list.","Route pay-rate, tax, super, leave, award, termination, or statutory questions.","Support draft payroll review.","Submit or declare only if explicitly authorized and qualified.","Store reports and evidence securely."]},{"type":"callout","title":"Stay inside the role","text":"Do not determine awards, pay rates, PAYG treatment, super obligations, leave entitlements, termination payments, or STP declarations from your own judgment."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Editing pay rates from an employee email","Submitting STP using someone else''s authority","Sharing payroll reports broadly","Guessing leave treatment","Treating software calculation as proof setup is correct"]},{"type":"scenario","title":"Practice scenario","text":"An employee says their overtime rate is wrong and asks you to change it before payroll closes. Describe the evidence and approval path."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Payroll data is high sensitivity.","Prepare inputs and exceptions.","Keep statutory judgment with qualified owners.","Document approvals."]}]'::jsonb,30,2,false,1,null,null,now(),now())
