insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-bookkeeping-administration') and position=4),'month-end-preparation-reports-and-accountant-handoff','Month-End Preparation, Reports, and Accountant Handoff','Month-end is where incomplete bills, missing receipts, unreconciled bank items, overdue invoices, payroll issues, and coding questions become visible. A VA can make review faster by preparing a clean exception pack.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Build a month-end admin checklist","Prepare useful outstanding-item reports","Avoid presenting unreviewed accounts as final"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Month-end is where incomplete bills, missing receipts, unreconciled bank items, overdue invoices, payroll issues, and coding questions become visible. A VA can make review faster by preparing a clean exception pack."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Month-end is a completeness and review process.","Unreconciled items need explanation or owner.","Outstanding AP and AR should reflect disputes and payments.","Reports depend on underlying data quality.","Reviewer questions should link to evidence."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm source documents are processed.","Review unreconciled bank items.","Review AP and AR exceptions.","Collect payroll and expense documentation.","Prepare missing-information requests.","Run approved draft reports.","Label them draft where appropriate.","Create an exception summary with links.","Hand off to the reviewer."]},{"type":"callout","title":"Stay inside the role","text":"Do not represent draft management reports as final accounts, tax returns, BAS, or professional conclusions unless the qualified reviewer has approved them."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Closing with exceptions hidden","Sending reports with no period","Changing coding to make totals look reasonable","Forgetting supplier or customer disputes","Asking vague reviewer questions"]},{"type":"scenario","title":"Practice scenario","text":"At month-end there are six unreconciled bank items, two missing supplier invoices, one disputed customer balance, and an unapproved payroll adjustment. Build the reviewer handoff."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Month-end is about completeness and exceptions.","Label draft information honestly.","Link evidence.","Make reviewer questions specific."]}]'::jsonb,30,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=30,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-bookkeeping-administration') and position=4),'australian-bookkeeping-composite-admin-simulation','Australian Bookkeeping Composite Admin Simulation','This simulation tests whether you can prepare accurate finance administration without acting as the accountant, tax or BAS agent, or payroll authority.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Run a mixed Australian finance-admin queue","Separate routine preparation from regulated judgment","Produce an accountant-ready exception pack"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"This simulation tests whether you can prepare accurate finance administration without acting as the accountant, tax or BAS agent, or payroll authority."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Source documents","Accounts payable","Accounts receivable","Bank reconciliation","GST and BAS awareness","Payroll and STP","Month-end"]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review the fictional records.","Identify duplicates and missing documents.","Prepare AP and AR actions.","Investigate bank-feed exceptions.","Prepare a payroll input issue.","Flag GST or BAS-sensitive questions.","Build the month-end handoff."]},{"type":"callout","title":"Stay inside the role","text":"Do not determine tax treatment, lodge BAS, declare STP, approve payments beyond authority, calculate statutory entitlements, or write off balances."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Optimizing for clean reports instead of correct records","Accepting software suggestions blindly","Changing GST codes","Hiding payroll anomalies","Failing to preserve source evidence"]},{"type":"scenario","title":"Practice scenario","text":"A fictional Australian consultancy has duplicate bills, an overdue customer invoice, a supplier bank-detail change, four bank-feed exceptions, a questionable GST code, and an overtime dispute before payroll. Prepare the safe admin workflow and handoff."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Evidence before entries.","Approval before money movement.","Exceptions before final reports.","Professional judgment stays with qualified owners."]}]'::jsonb,30,2,false,1,null,null,now(),now())
